contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= depositAmount, "insufficient balance");

        // Initialize MinSum
        c.SetMinSum(0);
        c.Initialized();

        // Deposit
        c.Deposit{value: depositAmount}();

        uint balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        // Decide whether collect should succeed
        bool shouldRevert = (balBefore < c.MinSum() || balBefore < collectAmount);

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (shouldRevert) {
            assert(reverted);
        } else {
            assert(!reverted);
        }

        if (!reverted) {
            assert(c.balances(address(this)) == balBefore - collectAmount);
            assert(address(c).balance == cBalBefore - collectAmount);
            assert(address(this).balance >= collectAmount);
        }
    }

    receive() external payable {}
}

